def tally(eg):
    seen = {"value": 0, "key": 0, "left": []}
    try:
        try:
            raise eg
        except* ValueError as g:
            seen["value"] = len(g.exceptions)
        except* KeyError as g:
            seen["key"] = len(g.exceptions)
    except ExceptionGroup as rest:
        seen["left"] = [type(e).__name__ for e in rest.exceptions]
    return seen

batch = ExceptionGroup("batch", [ValueError("a"), KeyError("k"), ValueError("b"), TypeError("t")])
print(tally(batch))
